import API from'../api/api-client.js';import AppState from'../core/app-state.js';import InteractiveACLBuilder from'./interactive-acl-builder.js';let commandPanel,keyspacePanel,integratedPanel;let commandIntegrateBtn,keyspaceIntegrateBtn,splitModeBtn;let commandInput,keyspaceInput,integratedCommandInput,integratedKeyInput;let integratedTestBtn,integratedResultDiv,keyPermissionHint;let integratedDismissTimeout=null;export function initIntegratedTester(){commandPanel=document.getElementById('command-tester-panel');keyspacePanel=document.getElementById('keyspace-tester-panel');integratedPanel=document.getElementById('integrated-tester-panel');commandIntegrateBtn=document.getElementById('command-integrate-btn');keyspaceIntegrateBtn=document.getElementById('keyspace-integrate-btn');splitModeBtn=document.getElementById('split-mode-btn');commandInput=document.getElementById('testCommand');keyspaceInput=document.getElementById('testKeyspace');integratedCommandInput=document.getElementById('integratedCommand');integratedKeyInput=document.getElementById('integratedKey');integratedTestBtn=document.getElementById('integrated-test-btn');integratedResultDiv=document.getElementById('integratedTestResult');keyPermissionHint=document.getElementById('key-permission-hint');if(commandIntegrateBtn){commandIntegrateBtn.addEventListener('click',enterIntegratedMode);}
if(keyspaceIntegrateBtn){keyspaceIntegrateBtn.addEventListener('click',enterIntegratedMode);}
if(splitModeBtn){splitModeBtn.addEventListener('click',exitIntegratedMode);}
if(integratedTestBtn){integratedTestBtn.addEventListener('click',testIntegrated);}
if(integratedCommandInput&&integratedKeyInput){integratedCommandInput.addEventListener('input',updateIntegratedButtonState);integratedKeyInput.addEventListener('input',updateIntegratedButtonState);}
restoreIntegratedModeState();}
function enterIntegratedMode(){if(!commandPanel||!keyspacePanel||!integratedPanel)return;localStorage.setItem('testerMode','integrated');commandPanel.style.transition='opacity 200ms ease-out';keyspacePanel.style.transition='opacity 200ms ease-out';commandPanel.style.opacity='0';keyspacePanel.style.opacity='0';setTimeout(()=>{commandPanel.style.display='none';keyspacePanel.style.display='none';integratedPanel.style.display='block';integratedPanel.style.opacity='0';integratedPanel.style.transition='opacity 300ms ease-in';if(commandInput&&integratedCommandInput){integratedCommandInput.value=commandInput.value;}
if(keyspaceInput&&integratedKeyInput){integratedKeyInput.value=keyspaceInput.value;}
checkForKeyPermissions();updateIntegratedButtonState();setTimeout(()=>{integratedPanel.style.opacity='1';setTimeout(()=>{integratedPanel.style.transition='';integratedPanel.style.opacity='';integratedPanel.style.display='';},300);},10);},200);}
function exitIntegratedMode(){if(!commandPanel||!keyspacePanel||!integratedPanel)return;localStorage.setItem('testerMode','split');integratedPanel.style.transition='opacity 200ms ease-out';integratedPanel.style.opacity='0';setTimeout(()=>{integratedPanel.style.display='none';if(integratedCommandInput&&commandInput){commandInput.value=integratedCommandInput.value;}
if(integratedKeyInput&&keyspaceInput){keyspaceInput.value=integratedKeyInput.value;}
commandPanel.style.display='block';keyspacePanel.style.display='block';commandPanel.style.opacity='0';keyspacePanel.style.opacity='0';commandPanel.style.transition='opacity 300ms ease-in';keyspacePanel.style.transition='opacity 300ms ease-in';if(integratedResultDiv){integratedResultDiv.textContent='';}
updateSplitButtonStates();setTimeout(()=>{commandPanel.style.opacity='1';keyspacePanel.style.opacity='1';setTimeout(()=>{commandPanel.style.transition='';commandPanel.style.opacity='';commandPanel.style.display='';keyspacePanel.style.transition='';keyspacePanel.style.opacity='';keyspacePanel.style.display='';},300);},10);},200);}
async function testIntegrated(){if(!integratedCommandInput||!integratedKeyInput||!integratedResultDiv)return;const command=integratedCommandInput.value.trim();const key=integratedKeyInput.value.trim();const rule=InteractiveACLBuilder.getLastValidRule();if(!command||!key){showIntegratedResult({is_allowed:false,command:command||'(empty)',key:key||'(empty)',reason:'Both command and key are required',command_granted:false,key_access_granted:false,command_categories:[]},true);return;}
try{const result=await API.testCommandKey(rule,command,key,AppState.currentVersion);showIntegratedResult(result,false);}catch(error){showIntegratedResult({is_allowed:false,command:command,key:key,reason:`Error: ${error.message}`,command_granted:false,key_access_granted:false,command_categories:[]},true);}}
function showIntegratedResult(result,isError){if(!integratedResultDiv)return;const statusClass=result.is_allowed?'success':'error';const statusIcon=result.is_allowed?'✅':'❌';const statusText=result.is_allowed?'ACCESS GRANTED':'ACCESS DENIED';integratedResultDiv.textContent='';const resultDiv=document.createElement('div');resultDiv.className=`integrated-result test-result ${statusClass}`;resultDiv.style.opacity='0';resultDiv.style.transform='scale(0.95)';const closeBtn=document.createElement('button');closeBtn.className='test-result-close';closeBtn.onclick=dismissIntegratedResult;closeBtn.setAttribute('aria-label','Dismiss result');closeBtn.textContent='✕';resultDiv.appendChild(closeBtn);const header=document.createElement('h4');header.className='result-header';header.textContent=`${statusIcon} ${statusText}`;resultDiv.appendChild(header);if(!isError){const breakdownDiv=document.createElement('div');breakdownDiv.className='breakdown';const commandCheckItem=document.createElement('div');commandCheckItem.className=`check-item ${result.command_granted ? 'pass' : 'fail'}`;commandCheckItem.appendChild(document.createTextNode(result.command_granted?'✅ ':'❌ '));const commandStrong=document.createElement('strong');commandStrong.textContent='Command Permission:';commandCheckItem.appendChild(commandStrong);commandCheckItem.appendChild(document.createTextNode(` ${result.command}`));if(result.command_categories&&result.command_categories.length>0){commandCheckItem.appendChild(document.createElement('br'));const categoriesSmall=document.createElement('small');categoriesSmall.className='categories';categoriesSmall.textContent=`Categories: ${result.command_categories.join(', ')}`;commandCheckItem.appendChild(categoriesSmall);}
breakdownDiv.appendChild(commandCheckItem);const keyCheckItem=document.createElement('div');keyCheckItem.className=`check-item ${result.key_access_granted ? 'pass' : 'fail'}`;keyCheckItem.appendChild(document.createTextNode(result.key_access_granted?'✅ ':'❌ '));const keyStrong=document.createElement('strong');keyStrong.textContent='Key Access:';keyCheckItem.appendChild(keyStrong);keyCheckItem.appendChild(document.createTextNode(` ${result.key}`));if(result.matched_pattern){keyCheckItem.appendChild(document.createElement('br'));const patternSmall=document.createElement('small');patternSmall.className='pattern-match';patternSmall.appendChild(document.createTextNode('Pattern: '));const patternCode=document.createElement('code');patternCode.textContent=result.matched_pattern;patternSmall.appendChild(patternCode);patternSmall.appendChild(document.createTextNode(' '));const permissionBadge=document.createElement('span');permissionBadge.className=`permission-badge ${result.permission_type}`;permissionBadge.textContent=`(${formatPermissionType(result.permission_type)})`;patternSmall.appendChild(permissionBadge);keyCheckItem.appendChild(patternSmall);}
breakdownDiv.appendChild(keyCheckItem);resultDiv.appendChild(breakdownDiv);}
const explanationDiv=document.createElement('div');explanationDiv.className='explanation';explanationDiv.textContent=result.reason;resultDiv.appendChild(explanationDiv);integratedResultDiv.appendChild(resultDiv);setTimeout(()=>{const resultEl=integratedResultDiv.querySelector('.integrated-result');if(resultEl){resultEl.style.transition='opacity 300ms ease-in, transform 300ms ease-in';resultEl.style.opacity='1';resultEl.style.transform='scale(1)';}},10);if(integratedDismissTimeout){clearTimeout(integratedDismissTimeout);}
integratedDismissTimeout=setTimeout(()=>{dismissIntegratedResult();integratedDismissTimeout=null;},15000);}
function dismissIntegratedResult(){if(!integratedResultDiv)return;if(integratedDismissTimeout){clearTimeout(integratedDismissTimeout);integratedDismissTimeout=null;}
integratedResultDiv.classList.add('dismissing');setTimeout(()=>{integratedResultDiv.textContent='';integratedResultDiv.classList.remove('dismissing');},400);}
window.dismissIntegratedResult=dismissIntegratedResult;function formatPermissionType(permissionType){const typeMap={'read-only':'%R~ read-only','write-only':'%W~ write-only','read-write':'~ read-write'};return typeMap[permissionType]||permissionType;}
function checkForKeyPermissions(){const rule=AppState.currentACLRule||'';const hasKeyPermissions=rule.includes('%R~')||rule.includes('%W~')||rule.includes('%RW~');if(keyPermissionHint){keyPermissionHint.style.display=hasKeyPermissions?'block':'none';}}
function updateIntegratedButtonState(){if(!integratedTestBtn||!integratedCommandInput||!integratedKeyInput)return;const hasCommand=integratedCommandInput.value.trim().length>0;const hasKey=integratedKeyInput.value.trim().length>0;integratedTestBtn.disabled=!hasCommand||!hasKey;}
export function updateKeyPermissionHint(){if(integratedPanel&&integratedPanel.style.display!=='none'){checkForKeyPermissions();}}
function restoreIntegratedModeState(){const savedMode=localStorage.getItem('testerMode');if(savedMode==='integrated'){if(integratedPanel){checkForKeyPermissions();updateIntegratedButtonState();}}else{setTimeout(()=>{updateSplitButtonStates();},100);}}
function updateSplitButtonStates(){const commandTestBtn=document.querySelector('.command-test-button');if(commandTestBtn&&commandInput){commandTestBtn.disabled=commandInput.value.trim().length===0;}
const keyspaceTestBtn=document.querySelector('.keyspace-test-button');if(keyspaceTestBtn&&keyspaceInput){keyspaceTestBtn.disabled=keyspaceInput.value.trim().length===0;}}
export default{initIntegratedTester,updateKeyPermissionHint};